package br.com.marquesautodetail.api.empresa;
import br.com.marquesautodetail.api.endereco.Endereco;import br.com.marquesautodetail.api.usuario.Usuario;import jakarta.persistence.*;
@Entity @Table(name="empresas") public class Empresa{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private String nomeFantasia; @Column(length=1000) private String descricao; private String telefone; private String cnpj; private String fotoUrl; private Double latitude; private Double longitude; private Double mediaAvaliacao=0.0; private Boolean aberta=true;
 @OneToOne @JoinColumn(name="usuario_id") private Usuario usuario; @OneToOne(cascade=CascadeType.ALL) @JoinColumn(name="endereco_id") private Endereco endereco;
 public Long getId(){return id;} public void setId(Long id){this.id=id;} public String getNomeFantasia(){return nomeFantasia;} public void setNomeFantasia(String nomeFantasia){this.nomeFantasia=nomeFantasia;} public String getDescricao(){return descricao;} public void setDescricao(String descricao){this.descricao=descricao;} public String getTelefone(){return telefone;} public void setTelefone(String telefone){this.telefone=telefone;} public String getCnpj(){return cnpj;} public void setCnpj(String cnpj){this.cnpj=cnpj;} public String getFotoUrl(){return fotoUrl;} public void setFotoUrl(String fotoUrl){this.fotoUrl=fotoUrl;} public Double getLatitude(){return latitude;} public void setLatitude(Double latitude){this.latitude=latitude;} public Double getLongitude(){return longitude;} public void setLongitude(Double longitude){this.longitude=longitude;} public Double getMediaAvaliacao(){return mediaAvaliacao;} public void setMediaAvaliacao(Double mediaAvaliacao){this.mediaAvaliacao=mediaAvaliacao;} public Boolean getAberta(){return aberta;} public void setAberta(Boolean aberta){this.aberta=aberta;} public Usuario getUsuario(){return usuario;} public void setUsuario(Usuario usuario){this.usuario=usuario;} public Endereco getEndereco(){return endereco;} public void setEndereco(Endereco endereco){this.endereco=endereco;}
}
